let calcScrollValue = () => {
    let scrollProgress = document.getElementById("progress");
    let pos = document.documentElement.scrollTop;
    let calcHeight =
      document.documentElement.scrollHeight -
      document.documentElement.clientHeight;
    let scrollValue = Math.round((pos * 100) / calcHeight);
    if (pos > 100) {
      scrollProgress.style.display = "grid";
    } else {
      scrollProgress.style.display = "none";
    }
    scrollProgress.addEventListener("click", () => {
      smoothScrollToTop();
    });
    //Change icon background color
    scrollProgress.style.background = `conic-gradient(#62708a ${scrollValue}%, #2b3546 ${scrollValue}%)`;
  };

  let smoothScrollToTop = () => {
    const currentPosition = document.documentElement.scrollTop;
    const targetPosition = 0;
    const duration = 1000; // Time in milliseconds for smooth scroll animation

    let startTime = null;

    const animation = (currentTime) => {
      if (startTime === null) startTime = currentTime;
      const timeElapsed = currentTime - startTime;
      const ease = easeInOutQuad(timeElapsed, currentPosition, targetPosition - currentPosition, duration);

      document.documentElement.scrollTop = ease;

      if (timeElapsed < duration) {
        requestAnimationFrame(animation);
      }
    };

    requestAnimationFrame(animation);
  };

  // Easing function for smooth scroll animation
  const easeInOutQuad = (t, b, c, d) => {
    t /= d / 2;
    if (t < 1) return (c / 2) * t * t + b;
    t--;
    return (-c / 2) * (t * (t - 2) - 1) + b;
  };

  window.onscroll = calcScrollValue;
  window.onload = calcScrollValue;
